<?php if ($tab==='today'): $todayTasks=$dayTasks; $todayRoutines=array_filter($routines,fn($r)=>$r['active'] && in_array((string)ui_date('N',strtotime($date)),explode(',',$r['days']),true)); $todayAppointments=$dayAppointments; ?>
<div class="stats"><section class="card"><p class="muted"><?= e(t('Tasks due or undated')) ?></p><div class="big-number"><?= e($dayTaskCount) ?></div><small><?= e(t('Up to 200 shown below')) ?></small></section><section class="card"><p class="muted"><?= e(t('Routines scheduled')) ?></p><div class="big-number"><?= count($todayRoutines) ?></div></section><section class="card"><p class="muted"><?= e(t('Appointments')) ?></p><div class="big-number"><?= count($todayAppointments) ?></div></section></div>
