<section class="card"><div class="section-heading"><h2><?= e(t('Build a little consistency')) ?></h2><a href="/planner?view=habits&amp;date=<?= e($date) ?>"><?= e(t('Open habits →')) ?></a></div><p class="muted"><?php $activeHabits=array_filter($habits,fn($h)=>$h['active']); ?><?= count($activeHabits) ? count(array_filter($activeHabits,fn($h)=>$h['checked'])).' of '.count($activeHabits).' active habits checked for this day.' : t('No data yet. Choose one habit you want to practice.') ?></p></section>
<?php elseif ($tab==='tasks'): ?>
<div class="two-col"><section class="card"><h2><?= e(t('Tasks')) ?></h2><p class="muted"><?= e(t('Find your next step. Completing a lesson action also applies its lesson.')) ?></p>
