<p class="task-result-count" role="status"><?= count($tasks) ?> <?= e(t('of')) ?> <?= e($taskList['total']) ?> <?= e(t('matching tasks')) ?><?= $taskList['filter']==='overdue' ? ' - Due before '.e($date) : '' ?>.<?= $taskList['total']>200 ? ' Showing the first 200. Narrow your search to find more.' : '' ?> <?php if ($taskList['filter']!=='all' || $taskList['search']!==''): ?><a href="/planner?view=tasks&amp;date=<?= e($date) ?>"><?= e(t('Clear filters')) ?></a><?php endif; ?></p><?php if (!$tasks): ?><p class="muted"><?= $taskList['filter']!=='all' || $taskList['search']!=='' ? t('No tasks match these filters. Try another title or status.') : t('No data yet. Add your first task.') ?></p><?php else: foreach ($tasks as $t): ?><article class="lesson-entry"><div class="section-heading"><div><strong><?= e($t['title']) ?></strong><small><?= e($t['due'] ?? t('No due date')) ?> · <?= e($t['status']) ?> · <?= e($t['source'] ?? 'manual') ?></small></div><form method="post" action="/planner/tasks/<?= e($t['id']) ?>/status"><?= csrf_field() ?><?php require __DIR__.'/task-context.php'; ?><input type="hidden" name="status" value="<?= $t['status']==='done' ? 'open' : 'done' ?>"><button class="secondary"><?= $t['status']==='done' ? t('Reopen') : t('Done') ?></button></form></div><?php if ($t['archived_at']): ?><form action="/planner/tasks/<?= e($t['id']) ?>/unarchive" method="post"><?= csrf_field() ?><button class="secondary"><?= e(t('Restore from archive')) ?></button></form><?php endif; ?><details><summary><?= e(t('Edit task')) ?></summary><form class="stack" method="post" action="/planner/tasks/<?= e($t['id']) ?>/edit"><?= csrf_field() ?><?php require __DIR__.'/task-context.php'; ?><label><?= e(t('Task')) ?><input name="title" maxlength="200" value="<?= e($t['title']) ?>" required></label><label><?= e(t('Due date')) ?><input type="date" name="due" value="<?= e($t['due']) ?>"></label><label><?= e(t('Priority')) ?><select name="priority"><?php foreach (['low','normal','high'] as $priority): ?><option <?= ($t['priority'] ?? 'normal')===$priority?'selected':'' ?>><?= e($priority) ?></option><?php endforeach; ?></select></label><label><?= e(t('Estimated minutes')) ?><input name="estimate_minutes" type="number" min="5" max="480" value="<?= e($t['estimate_minutes'] ?? 30) ?>" required></label><label><?= e(t('Hard deadline (optional)')) ?><input name="deadline" type="date" value="<?= e($t['deadline'] ?? '') ?>"></label><button class="secondary"><?= e(t('Save task')) ?></button></form></details><?php if ($t['source']!=='lesson'): ?><form method="post" action="/planner/tasks/<?= e($t['id']) ?>/delete" data-confirm="Delete this task?"><?= csrf_field() ?><?php require __DIR__.'/task-context.php'; ?><button class="delete"><?= e(t('Delete')) ?></button></form><?php endif; ?></article><?php endforeach; endif; ?></section><section class="card" id="new-task"><h2><?= e(t('Add a task')) ?></h2><form class="stack" action="/planner/tasks" method="post"><?= csrf_field() ?><label><?= e(t('What needs doing?')) ?><input name="title" maxlength="200" required></label><label><?= e(t('Due date (optional)')) ?><input name="due" type="date"></label><label><?= e(t('Priority')) ?><select name="priority"><?php foreach (['low','normal','high'] as $priority): ?><option <?= ($newTask['priority'] ?? 'normal')===$priority?'selected':'' ?>><?= e($priority) ?></option><?php endforeach; ?></select></label><label><?= e(t('Estimated minutes')) ?><input name="estimate_minutes" type="number" min="5" max="480" value="<?= e($newTask['estimate_minutes'] ?? 30) ?>" required></label><label><?= e(t('Hard deadline (optional)')) ?><input name="deadline" type="date" value="<?= e($newTask['deadline'] ?? '') ?>"></label><button><?= e(t('Add task')) ?></button></form></section></div>
<?php elseif ($tab==='habits'): ?>
<div class="two-col"><section class="card"><h2><?= e(t('Your habits')) ?></h2><p class="muted"><?= e(t('Check-ins for')) ?> <?= e($date) ?><?= e(t('. Streaks count consecutive days through today or yesterday.')) ?></p><?php if (!$habits): ?><p class="muted"><?= e(t('No data yet. Start with one small habit.')) ?></p><?php else: foreach ($habits as $h): ?><article class="lesson-entry"><div class="section-heading"><div><strong><?= e($h['title']) ?></strong><small><?= $h['active'] ? t('Active') : t('Paused') ?> · <?= e($h['streak']) ?> <?= e(t('day streak ·')) ?> <?= e($h['week_count']) ?><?= e(t('/7 recent check-ins')) ?></small></div><?php if ($h['active'] && $date<=ui_date('Y-m-d')): ?><form method="post" action="/planner/habits/<?= e($h['id']) ?>/check"><?= csrf_field() ?><input type="hidden" name="date" value="<?= e($date) ?>"><button class="secondary"><?= $h['checked'] ? t('Undo check-in') : t('Check in') ?></button></form><?php endif; ?></div><p class="muted"><?= e($h['notes']) ?></p><details><summary><?= e(t('Edit habit')) ?></summary><?php $record=$h; $formType='habits'; require __DIR__.'/record-form.php'; unset($record); ?></details><form method="post" action="/planner/habits/<?= e($h['id']) ?>/delete" data-confirm="Delete this habit and its check-in history?"><?= csrf_field() ?><button class="delete"><?= e(t('Delete habit')) ?></button></form></article><?php endforeach; endif; ?></section><section class="card"><h2><?= e(t('Add a habit')) ?></h2><?php $formType='habits'; require __DIR__.'/record-form.php'; ?></section></div>
<?php elseif ($tab==='routines'): ?>
<div class="two-col"><section class="card"><h2><?= e(t('Your routines')) ?></h2><?php if (!$routines): ?><p class="muted"><?= e(t('No data yet. Build a routine around your actual week.')) ?></p><?php else: foreach ($routines as $r): $scheduled=$r['active'] && in_array((string)ui_date('N',strtotime($date)),explode(',',$r['days']),true); ?><article class="lesson-entry"><div class="section-heading"><div><strong><?= e($r['time']) ?> · <?= e($r['title']) ?></strong><small><?= e(implode(', ',array_map(fn($d)=>PlannerService::DAYS[(int)$d],explode(',',$r['days'])))) ?> · <?= $r['active'] ? t('Active') : t('Paused') ?></small></div><?php if ($scheduled && $date<=ui_date('Y-m-d')): ?><form action="/planner/routines/<?= e($r['id']) ?>/check" method="post"><?= csrf_field() ?><input type="hidden" name="date" value="<?= e($date) ?>"><button class="secondary"><?= $r['checked'] ? t('Undo') : t('Complete') ?></button></form><?php endif; ?></div><details><summary><?= e(t('Edit routine')) ?></summary><?php $record=$r; $formType='routines'; require __DIR__.'/record-form.php'; unset($record); ?></details><form method="post" action="/planner/routines/<?= e($r['id']) ?>/delete" data-confirm="Delete this routine and its completion history?"><?= csrf_field() ?><button class="delete"><?= e(t('Delete routine')) ?></button></form></article><?php endforeach; endif; ?></section><section class="card"><h2><?= e(t('Add a routine')) ?></h2><?php $formType='routines'; require __DIR__.'/record-form.php'; ?></section></div>
<?php else: ?>
<div class="two-col"><section class="card"><h2><?= e(t('Appointments')) ?></h2><p class="muted"><?= e(t('Latest 100 appointments. Reminder times are saved with the appointment.')) ?></p><?php if (!$appointments): ?><p class="muted"><?= e(t('No data yet. Add an appointment or meeting.')) ?></p><?php else: foreach ($appointments as $a): ?><article class="lesson-entry"><strong><?= e($a['title']) ?></strong><small><?= e($a['starts_at']) ?> → <?= e($a['ends_at']) ?> · <?= e($a['status']) ?></small><p class="muted"><?= e($a['location']) ?></p><small><?= e(t('Reminder')) ?> <?= e($a['reminder_minutes']) ?> <?= e(t('minutes before')) ?></small><details><summary><?= e(t('Edit appointment')) ?></summary><?php $record=$a; $formType='appointments'; require __DIR__.'/record-form.php'; unset($record); ?></details><form action="/planner/appointments/<?= e($a['id']) ?>/delete" method="post" data-confirm="Delete this appointment?"><?= csrf_field() ?><button class="delete"><?= e(t('Delete appointment')) ?></button></form></article><?php endforeach; endif; ?></section><section class="card"><h2><?= e(t('Add an appointment')) ?></h2><?php $formType='appointments'; require __DIR__.'/record-form.php'; ?></section></div>
